<?php require __DIR__.'/../app/bootstrap.php';$u=require_admin();$title='Admin activity';$logs=all('SELECT a.*,u.full_name FROM audit_logs a JOIN users u ON u.id=a.admin_id ORDER BY a.id DESC LIMIT 200');require ROOT.'/app/workspace-start.php'; ?>
<div class="page-heading"><h1>Admin activity</h1><p>The latest 200 category changes and seller decisions.</p></div><section class="panel"><?php if(!$logs): ?><p class="empty">No admin activity recorded yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Administrator</th><th>Action</th><th>Record ID</th><th>Time</th></tr></thead><tbody><?php foreach($logs as $log): ?><tr><td><?=e($log['full_name'])?></td><td><?=e($log['action'])?></td><td>#<?=$log['target_id']?></td><td><?=e(local_time($log['created_at']))?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?></section><?php require ROOT.'/app/workspace-end.php'; ?>
